syntax:
for (khoi_tao; dieu_kien; cap_nhat) {
    // Thân vòng lặp
}

example:
#include <iostream>
int main() {
    int sum = 0;
    for (int i = 1; i <= 10; ++i) sum += i;
    std::cout << sum << '\n'; // 55
}

#include <iostream>
int main() {
    int n = 1234, digits = 0;
    while (n > 0) { digits++; n /= 10; }
    std::cout << digits << '\n'; // 4
}

#include <iostream>
int main() {
    int n;
    do {
        std::cin >> n;
    } while (n <= 0); // Ép nhập số dương
}

syntax:
for (auto& x : container) {
    // Thao tác trực tiếp trên x
}

example:
#include <iostream>
int main() {
    int a[4] = {10, 20, 30, 40};
    for (int x : a) std::cout << x << ' ';
}
